p { color: gray; }
.tarjeta { padding: 1rem; }
#header { position: sticky; }

a:hover { text-decoration: underline; }
input:focus { outline: 2px solid blue; }
li:nth-child(2n) { background: #f5f5f5; }
button:not(.disabled) { cursor: pointer; }

.card::before {
  content: "★";
  margin-right: 0.5rem;
}
input::placeholder {
  color: #999;
}

input[type="email"] { border-color: blue; }
a[href^="https"] { color: green; }
a[href$=".pdf"] { color: red; }

*, *::before, *::after {
  box-sizing: border-box;
}

.caja {
  padding: 1rem 2rem;       /* vertical horizontal */
  margin: 0 auto;           /* centra horizontalmente si tiene ancho fijo */
  border: 1px solid #ddd;
}

.contenedor {
  width: 800px;
  max-width: 100%;
  margin-inline: auto;
}

.contenedor {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.item-principal {
  flex: 1;          /* crece para ocupar el espacio disponible */
}
.item-fijo {
  flex: 0 0 200px;  /* no crece, no encoge, 200px de base */
}

.contenedor {
  display: flex;
  flex-direction: column;
  flex-wrap: wrap;
}

.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 1rem;
}

.layout {
  display: grid;
  grid-template-columns: 200px 1fr;
  grid-template-areas:
    "sidebar header"
    "sidebar contenido";
}
.sidebar { grid-area: sidebar; }
.header  { grid-area: header; }

:root {
  --color-primario: #2563eb;
  --espaciado-base: 1rem;
}

.boton {
  background: var(--color-primario);
  padding: var(--espaciado-base);
}

.texto {
  color: var(--color-texto, #333);
}

:root {
  --bg: #ffffff;
  --text: #111111;
}

[data-theme="dark"] {
  --bg: #111111;
  --text: #f5f5f5;
}

body {
  background: var(--bg);
  color: var(--text);
}

.boton {
  background: #2563eb;
  transition: background 0.2s ease, transform 0.2s ease;
}
.boton:hover {
  background: #1d4ed8;
  transform: translateY(-2px);
}

@keyframes fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

.tarjeta {
  animation: fade-in 0.4s ease-out;
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

.columna {
  width: 100%;
}

@media (min-width: 768px) {
  .columna {
    width: 50%;
  }
}

.titulo {
  font-size: 2rem;      /* relativo al font-size del <html> */
  width: 90%;           /* relativo al contenedor padre */
  min-height: 50vh;     /* mitad de la altura de la ventana */
}

.titulo {
  font-size: clamp(1.5rem, 4vw, 3rem);
}
